const ctx = $('When Called').first().json;
const c = $input.first().json;
const eventType = ctx.event_type || 'case_update';
const name = c.first_name || 'Client';
const caseId = ctx.case_id || c.case_id;

const WEC_PHONE = '(833) WEC-9933';
const WEC_EMAIL = 'info@WilliamsEquityCapital.com';
const PORTAL_URL = 'https://www.williamsequitycapital.com/portal';
const sig = `

Williams Equity Capital
${WEC_PHONE} | ${WEC_EMAIL}
Case: ${caseId}`;

const messages = {
  intake_confirmed: {
    subject: 'Your WEC Credit Repair Case Is Open',
    body: `Hi ${name},

Your case with Williams Equity Capital has been opened successfully. Here's what happens next:

• Your 3-day CROA cancellation window is now open
• You may cancel for a full refund before the deadline
• After the window closes, your credit report will be pulled and analyzed
• Dispute letters will be drafted and sent for your review

You owe NOTHING until services are performed.

Log in to your portal to track progress: ${PORTAL_URL}${sig}`
  },
  letters_ready: {
    subject: 'Your Dispute Letters Are Ready for Review',
    body: `Hi ${name},

Your FCRA dispute letters have been drafted by our compliance team. They are currently under final review before certified mail dispatch.

Your letters will be sent to:
• Experian
• TransUnion
• Equifax

Each bureau has 30 days to respond under 15 U.S.C. § 1681i.

View your letters: ${PORTAL_URL}${sig}`
  },
  letters_mailed: {
    subject: 'Your Dispute Letters Have Been Mailed',
    body: `Hi ${name},

Your dispute letters have been mailed via USPS Certified Mail with Return Receipt Requested.

Under the FCRA (15 U.S.C. § 1681i), the credit bureaus have 30 days to complete their investigation and respond.

We will monitor for responses and notify you immediately when a bureau replies.

Track your case: ${PORTAL_URL}${sig}`
  },
  bureau_response_received: {
    subject: 'Bureau Response Received — Action Required',
    body: `Hi ${name},

We have received a response from a credit bureau regarding your disputes.

Our team is evaluating the response and will determine if any items were resolved. If items remain inaccurate, we will escalate to the next dispute round.

Log in to see the update: ${PORTAL_URL}${sig}`
  },
  escalated_round_2: {
    subject: 'Escalating to Round 2 — Method of Verification Demand',
    body: `Hi ${name},

The credit bureaus did not fully resolve your disputes in Round 1. We are escalating to Round 2.

Round 2 sends a formal Method of Verification demand under 15 U.S.C. § 1681i(a)(7), requiring the bureau to disclose exactly how they verified the disputed items. This is a stronger legal position.

Log in for details: ${PORTAL_URL}${sig}`
  },
  escalated_round_3: {
    subject: 'Escalating to Round 3 — Pre-Litigation Demand',
    body: `Hi ${name},

After two rounds of disputes, unresolved items remain. We are escalating to Round 3.

Round 3 letters cite § 1681n (Willful FCRA Noncompliance) and warn of civil action. This is our strongest pre-litigation position.

If Round 3 fails, you may have grounds to sue the credit bureau for damages. We recommend consulting with a consumer rights attorney.

Log in: ${PORTAL_URL}${sig}`
  },
  legal_action_recommended: {
    subject: 'Dispute Process Complete — Legal Action May Be Available',
    body: `Hi ${name},

We have completed all dispute rounds on your behalf. Some items may still remain.

Based on the bureaus' failure to correct demonstrably inaccurate information after proper dispute, you may have grounds for civil litigation under:
• 15 U.S.C. § 1681n (Willful noncompliance — up to $1,000 per violation + punitive damages)
• 15 U.S.C. § 1681o (Negligent noncompliance)

We recommend consulting with a FCRA/FDCPA attorney. Our Legal Letters tool can help you draft demand letters.

${PORTAL_URL}${sig}`
  },
  case_resolved: {
    subject: '🎉 Your Credit Repair Case Has Been Resolved',
    body: `Hi ${name},

Congratulations! We are pleased to report that all disputable items in your case have been resolved.

Your updated credit reports should reflect the corrections within the next 30-60 days as the bureaus update their databases.

Tips to maintain your improved credit:
• Pay all accounts on time
• Keep utilization below 30%
• Avoid opening multiple new accounts

Thank you for trusting Williams Equity Capital.

${PORTAL_URL}${sig}`
  },
  compliance_alert: {
    subject: 'Important Compliance Notice — Action Required',
    body: `Hi ${name},

We need to bring an important compliance matter to your attention regarding your credit repair case.

Please log in to your portal immediately for details: ${PORTAL_URL}

If you have questions, contact us at ${WEC_EMAIL} or ${WEC_PHONE}.${sig}`
  }
};

const msg = messages[eventType] || {
  subject: 'Update on Your Williams Equity Capital Case',
  body: `Hi ${name},

There is an update on your credit repair case (${caseId}). Please log in to your portal for details: ${PORTAL_URL}${sig}`
};

return [{ json: {
  case_id: caseId,
  event_type: eventType,
  email: c.email,
  phone: c.phone,
  sms_opt_in: c.sms_opt_in,
  subject: msg.subject,
  body: msg.body
} }];

const resp = $input.first().json;
const msg = $('Build Message').first().json;
const channel = resp.sid ? 'sms' : 'email';
return [{ json: { case_id: msg.case_id, event_type: msg.event_type, channel } }];
